import { _decorator, Component, Sprite, Color } from 'cc';
import type { Bus } from '../../Engine/Bus';
import { HallEvents } from '../HallEvents';
import { gridToWorld } from '../Config/GridConfig';
import type { GhostState } from '../Data/GhostState';

const { ccclass } = _decorator;

@ccclass('GhostView')
export class GhostView extends Component {
    private _bus: Bus = null!;
    private _sprite: Sprite = null!;

    onLoad() {
        this._sprite = this.getComponent(Sprite)!;
        this.node.active = false; 
    }

    public setup(bus: Bus) {
        this._bus = bus;
        this._bus.on(HallEvents.GHOST_STATE_CHANGED, this._onStateChanged, this);
    }

    onDestroy() {
        this._bus?.off(HallEvents.GHOST_STATE_CHANGED, this._onStateChanged, this);
    }

    private _onStateChanged(state: GhostState) {
        this.node.active = state.active;
        if (!state.active) return;

        const pos = gridToWorld(state.gridX, state.gridY);
        this.node.setPosition(pos.x, pos.y);

        // 直接根据 valid 换颜色
        if (state.valid) {
            this._sprite.color = new Color(100, 255, 100, 150); 
        } else {
            this._sprite.color = new Color(255, 100, 100, 150); 
        }
    }
}